  const [templates, setTemplates] = useState<AnyObj[]>([]); const [msgLogs, setMsgLogs] = useState<AnyObj[]>([]); const [showMsgLogs, setShowMsgLogs] = useState(false);
  const [saveTplName, setSaveTplName] = useState('');
